// NBIRTH: the edge node's own birth certificate, published once before any DBIRTH.
// Real Sparkplug B NBIRTH also carries a bdSeq (birth/death sequence) metric, omitted
// here because the ingestion engine's JSON-fallback parser (used by this simulator)
// only understands string_value/double_value/boolean_value metrics, not long_value.
const topic = 'spBv1.0/FactoryPlus/NBIRTH/gwy100000000000400080000';
const spbNBirthPayload = {
    timestamp: Date.now(),
    // Factory+ birth profile. The payload `uuid` identifies this as a Factory+ Sparkplug
    // packet; Instance_UUID and Schema_UUID are the asset's RFC4122 identity and the model
    // it conforms to. Additive -- the topic's sparkplug_id remains this platform's identity.
    //
    // NO Schema_UUID HERE, deliberately. Factory+'s component schema
    // (05688a03-730e-4cda-9932-172e2c62e45c) asserts that the publisher is a Factory+
    // COMPONENT serving a Service_UUID at a Service_URL. This edge node is not one, so
    // claiming it would assert an interoperability that does not exist. Instance_UUID is
    // a fact about the gateway; a schema id it does not implement would be a fiction.
    uuid: '11ad7b32-1d32-4c4a-b0c9-fa049208939a',
    metrics: [
        { name: 'Instance_UUID', string_value: '10000000-0000-4000-8000-000000000001', datatype: 12 },
        { name: 'Gateway_Status', string_value: 'ONLINE', datatype: 12 }
    ],
    seq: 0
};
return { topic: topic, payload: JSON.stringify(spbNBirthPayload), qos: 0, retain: false };

// Periodic rebirth so a consumer that starts after Node-RED still receives the
// birth certificate. Stays silent while the device is in its DDEATH state, so the
// DDEATH demo is not undone by the next rebirth tick.
if (global.get('device_alive') === false) {
    return null;
}
global.set('device_alive', true);
const topic = 'spBv1.0/FactoryPlus/DBIRTH/gwy100000000000400080000/dev200000000000400080000';
const spbBirthPayload = {
    timestamp: Date.now(),
    // Factory+ birth profile. The payload `uuid` identifies this as a Factory+ Sparkplug
    // packet; Instance_UUID and Schema_UUID are the asset's RFC4122 identity and the model
    // it conforms to. Additive -- the topic's sparkplug_id remains this platform's identity.
    uuid: '11ad7b32-1d32-4c4a-b0c9-fa049208939a',
    metrics: [
        { name: 'Instance_UUID', string_value: '20000000-0000-4000-8000-000000000002', datatype: 12 },
        { name: 'Schema_UUID',   string_value: 'e3333333-4444-5555-6666-777777777777', datatype: 12 },
        { name: 'Asset_ID',          string_value: 'dev200000000000400080000',  datatype: 12 },
        { name: 'Asset_Name', string_value: 'Simulated_CNC_01', datatype: 12 },
        { name: 'Controller/FIRMWARE',  string_value: 'v3.2.0-industrial', datatype: 12 },
        { name: 'SERIAL_NUMBER',     string_value: 'SN-CNC-8832',       datatype: 12 },
        { name: 'max_temp_threshold',double_value: 85.0,                datatype: 10 },
        { name: 'safety_interlock',  boolean_value: true,               datatype: 11 },
        // Sparkplug B requires DBIRTH to declare every metric the device will report in
        // DDATA, so the telemetry metrics are declared here at their nominal values.
        { name: 'Systems/TEMPERATURE',       double_value: 42.0,      datatype: 10 },
        { name: 'Axes/DISPLACEMENT',         double_value: 1.20,      datatype: 10 },
        { name: 'Controller/EXECUTION',      string_value: 'ACTIVE',  datatype: 12 },
        { name: 'Controller/EMERGENCY_STOP', string_value: 'ARMED',   datatype: 12 }
    ],
    seq: 0
};
return { topic: topic, payload: JSON.stringify(spbBirthPayload), qos: 0, retain: false };

if (global.get('device_alive') === false) {
    return null;
}
const topic = 'spBv1.0/FactoryPlus/DDATA/gwy100000000000400080000/dev200000000000400080000';
const tempOverride = global.get('temp_override');
const currentTemp = tempOverride !== undefined ? tempOverride : +(42.0 + Math.sin(Date.now() / 6000) * 5.0 + (Math.random() * 1.5)).toFixed(2);
const statusVal = global.get('status_override') || 'ACTIVE';
const safetyVal = (global.get('safety_override') !== undefined ? global.get('safety_override') : true) ? 'ARMED' : 'TRIGGERED';

const spbDataPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID',    string_value: 'dev200000000000400080000', datatype: 12 },
        { name: 'Asset_Name', string_value: 'Simulated_CNC_01', datatype: 12 },
        { name: 'Systems/TEMPERATURE', double_value: currentTemp,        datatype: 10 },
        { name: 'Axes/DISPLACEMENT',   double_value: 1.45,                datatype: 10 },
        { name: 'Controller/EXECUTION',      string_value: statusVal,          datatype: 12 },
        { name: 'Controller/EMERGENCY_STOP',   string_value: safetyVal,          datatype: 12 }
    ],
    seq: Math.floor(Math.random() * 255)
};
return { topic: topic, payload: JSON.stringify(spbDataPayload), qos: 0, retain: false };

global.set('device_alive', false);
const topic = 'spBv1.0/FactoryPlus/DDEATH/gwy100000000000400080000/dev200000000000400080000';
const spbDeathPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID', string_value: 'dev200000000000400080000', datatype: 12 },
        { name: 'Asset_Name', string_value: 'Simulated_CNC_01', datatype: 12 }
    ],
    seq: Math.floor(Math.random() * 255)
};
return { topic: topic, payload: JSON.stringify(spbDeathPayload), qos: 0, retain: false };

global.set('device_alive', true);
global.set('temp_override', 95.0);
global.set('status_override', 'ALARM_OVERHEAT');
global.set('safety_override', false);

const topic = 'spBv1.0/FactoryPlus/DDATA/gwy100000000000400080000/dev200000000000400080000';
const spbAlertPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID',    string_value: 'dev200000000000400080000', datatype: 12 },
        { name: 'Asset_Name', string_value: 'Simulated_CNC_01', datatype: 12 },
        { name: 'Systems/TEMPERATURE', double_value: 95.0,                datatype: 10 },
        { name: 'Axes/DISPLACEMENT',   double_value: 8.92,                datatype: 10 },
        { name: 'Controller/EXECUTION',      string_value: 'INTERRUPTED',   datatype: 12 },
        { name: 'Controller/EMERGENCY_STOP',   string_value: 'TRIGGERED',         datatype: 12 }
    ],
    seq: Math.floor(Math.random() * 255)
};
return { topic: topic, payload: JSON.stringify(spbAlertPayload), qos: 0, retain: false };

global.set('device_alive', true);
global.set('temp_override', undefined);
global.set('status_override', 'RUNNING');
global.set('safety_override', true);

const topic = 'spBv1.0/FactoryPlus/DDATA/gwy100000000000400080000/dev200000000000400080000';
const spbNormalPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID',    string_value: 'dev200000000000400080000', datatype: 12 },
        { name: 'Asset_Name', string_value: 'Simulated_CNC_01', datatype: 12 },
        { name: 'Systems/TEMPERATURE', double_value: 42.0,                datatype: 10 },
        { name: 'Axes/DISPLACEMENT',   double_value: 1.20,                datatype: 10 },
        { name: 'Controller/EXECUTION',      string_value: 'ACTIVE',          datatype: 12 },
        { name: 'Controller/EMERGENCY_STOP',   string_value: 'ARMED',             datatype: 12 }
    ],
    seq: Math.floor(Math.random() * 255)
};
return { topic: topic, payload: JSON.stringify(spbNormalPayload), qos: 0, retain: false };

const topic = 'spBv1.0/FactoryPlus/NDATA/gwy100000000000400080000';
const spbHeartbeatPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Gateway_Status', string_value: 'ONLINE', datatype: 12 }
    ],
    seq: Math.floor(Math.random() * 255)
};
return { topic: topic, payload: JSON.stringify(spbHeartbeatPayload), qos: 0, retain: false };

// Supabase posts the payload built by dispatch_device_quarantine_webhook().
const e = msg.payload || {};
node.warn(
    `QUARANTINE: ${e.sparkplug_id || e.device_id} (${e.name || "unnamed"}) ` +
    `reason=${e.quarantine_reason || "unspecified"} ` +
    `identity_source=${e.identity_source || "unknown"}`
);

// Replace this node to act on the event -- raise a ticket, page an operator, light an
// andon. The 200 below is returned regardless: pg_net does not retry, so failing the
// response would lose the event rather than redeliver it.
msg.statusCode = 200;
msg.payload = { received: true, sparkplug_id: e.sparkplug_id || null };
return msg;

// Answer a Sparkplug NCMD carrying `Node Control/Rebirth` by re-publishing this node's
// NBIRTH and then its DBIRTH -- which is what the specification requires of an Edge Node,
// and what lets the ingestion daemon recover its metric ALIAS TABLE after a restart.
//
// WHY A SUBSTRING PROBE AND NOT A PROTOBUF PARSE. The daemon publishes a real Sparkplug
// protobuf payload, and this image ships no protobuf library. A length-delimited protobuf
// string field carries its bytes verbatim, so the metric name appears literally in the
// buffer -- searching for it is reliable here even though it would not be a general decoder.
// A JSON payload is handled too, because the daemon's own fallback parser accepts one.
const REBIRTH = 'Node Control/Rebirth';
const MY_NODE = 'gwy100000000000400080000';

// Only answer a command addressed to THIS edge node. spBv1.0/<group>/NCMD/<edge_node>
const parts = (msg.topic || '').split('/');
if (parts[3] !== MY_NODE) { return null; }

const raw = msg.payload;
let wantsRebirth = false;

if (raw && typeof raw === 'object' && !Buffer.isBuffer(raw)) {
    // Already-parsed JSON.
    wantsRebirth = (raw.metrics || []).some(m => m.name === REBIRTH) || raw.Rebirth === true;
} else {
    const text = Buffer.isBuffer(raw) ? raw.toString('binary') : String(raw || '');
    try {
        const parsed = JSON.parse(text);
        wantsRebirth = (parsed.metrics || []).some(m => m.name === REBIRTH) || parsed.Rebirth === true;
    } catch (e) {
        wantsRebirth = text.indexOf(REBIRTH) !== -1;
    }
}

if (!wantsRebirth) { return null; }

node.warn('NCMD Node Control/Rebirth received -- re-publishing NBIRTH and DBIRTH');
// Both outputs carry an empty message: the birth builders construct their payloads from
// scratch and read nothing from the input. NBIRTH is wired first because it RESETS the
// node's alias table, and the DBIRTH that follows must merge into a fresh one.
return [{}, {}];
